pub fn run<'a>(
    config: &'a aws_config::SdkConfig,
    operation: &'a str,
    input: &'a Value,
    options: &'a Options,
) -> core::CommandFuture<'a> {
    Box::pin(async move {
        let mut config = aws_sdk_polly::config::Builder::from(config);
        if let Some(endpoint) = &options.endpoint_url {
            config = config.endpoint_url(endpoint);
        }
        let client = aws_sdk_polly::Client::from_conf(config.build());
        let output = Output::new(options.clone());
        let command: core::CommandFuture<'_> = match operation {
            "delete_lexicon" => Box::pin(call_delete_lexicon(&client, input, &output)),
            "describe_voices" => Box::pin(call_describe_voices(&client, input, &output)),
            "get_lexicon" => Box::pin(call_get_lexicon(&client, input, &output)),
            "get_speech_synthesis_task" => {
                Box::pin(call_get_speech_synthesis_task(&client, input, &output))
            }
            "list_lexicons" => Box::pin(call_list_lexicons(&client, input, &output)),
            "list_speech_synthesis_tasks" => {
                Box::pin(call_list_speech_synthesis_tasks(&client, input, &output))
            }
            "put_lexicon" => Box::pin(call_put_lexicon(&client, input, &output)),
            "start_speech_synthesis_stream" => {
                Box::pin(call_start_speech_synthesis_stream(&client, input, &output))
            }
            "start_speech_synthesis_task" => {
                Box::pin(call_start_speech_synthesis_task(&client, input, &output))
            }
            "synthesize_speech" => Box::pin(call_synthesize_speech(&client, input, &output)),
            _ => return Err(CliError::input(format!("unknown operation: {operation}"))),
        };
        command
            .await
            .map_err(|error| error.context("polly", operation))
    })
}
